// EDIT THESE TWO VALUES. Secrets belong in n8n credentials, never here.
const SETTINGS = {
  supabaseUrl: 'https://YOUR_PROJECT_REF.supabase.co',
  serviceId: 'website',
};
const input = $input.first().json;
const fromWebhook = Object.prototype.hasOwnProperty.call(input, 'headers')
  && Object.prototype.hasOwnProperty.call(input, 'body');
const request = fromWebhook ? input.body : input;
const now = new Date();
const previousMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)).toISOString().slice(0, 7);
const currentMonth = now.toISOString().slice(0, 7);
let validationError = null;
const objectBody = request && typeof request === 'object' && !Array.isArray(request);
const body = objectBody ? request : {};
if (!objectBody) validationError = 'Send a JSON object with Content-Type: application/json.';
if (fromWebhook && Object.keys(body).some(k => !['action', 'month', 'dataset'].includes(k))) {
  validationError = 'Allowed fields: action, month, dataset.';
}
const action = body.action ?? (fromWebhook ? 'status' : 'check');
const dataset = body.dataset ?? 'live';
const month = body.month ?? previousMonth;
if (!['check', 'status', 'report'].includes(action)) validationError = 'action must be check, status, or report.';
if (!['live', 'demo'].includes(dataset)) validationError = 'dataset must be live or demo.';
if (action === 'check' && dataset !== 'live') validationError = 'check always records live evidence; demo is for status/report only.';
if (action !== 'report' && body.month !== undefined) validationError = 'month is only valid for the report action.';
if (action === 'report' && (typeof month !== 'string' || !/^\d{4}-(0[1-9]|1[0-2])$/.test(month) || month < '1970-01' || month > currentMonth)) {
  validationError = 'month must be YYYY-MM between 1970-01 and the current UTC month.';
}
const supabaseUrl = SETTINGS.supabaseUrl.replace(/\/+$/, '');
if (!/^https:\/\/[^/\s]+$/.test(supabaseUrl) || supabaseUrl.includes('YOUR_PROJECT_REF')) {
  throw new Error('Set your Supabase Project URL in Settings and Request before running.');
}
return [{ json: {
  supabase_url: supabaseUrl, service_id: SETTINGS.serviceId,
  action, dataset, month: action === 'report' ? month + '-01' : null,
  from_webhook: fromWebhook, execution_id: String($execution.id),
  validation_error: validationError,
} }];

const s = $input.first().json;
if (!s.id || !s.target_url) throw new Error('Service row missing. Run schema.sql and check serviceId.');
if (!s.enabled) throw new Error('Service is disabled in sg_services.');
if (!/^https?:\/\//.test(s.target_url)) throw new Error('target_url must use http:// or https://.');
return [{ json: { ...s, started_at: new Date().toISOString() } }];

const raw = $input.first().json;
const service = $('Start Probe').first().json;
const settings = $('Settings and Request').first().json;
const status = Number(raw.statusCode);
const statusCode = Number.isInteger(status) && status >= 100 && status <= 599 ? status : null;
const transportError = raw.error;
const isUp = !transportError && statusCode === Number(service.expected_status);
let error = null;
if (transportError) {
  error = typeof transportError === 'string' ? transportError
    : (transportError.message || JSON.stringify(transportError));
} else if (!isUp) {
  error = statusCode === null ? 'No HTTP status returned' : `Expected HTTP ${service.expected_status}; received ${statusCode}`;
}
return [{ json: {
  p_service_id: settings.service_id, p_execution_id: settings.execution_id,
  p_checked_at: service.started_at, p_is_up: Boolean(isUp),
  p_status_code: statusCode,
  p_response_ms: Math.max(0, Date.now() - Date.parse(service.started_at)),
  p_error: error === null ? null : String(error).slice(0, 500),
} }];

const settings = $('Settings and Request').first().json;
const failed = Boolean(settings.validation_error);
const body = {
  ok: !failed, action: settings.action, execution_id: settings.execution_id,
  ...(failed ? { error: settings.validation_error } : { result: $input.first().json }),
};
return [{ json: { from_webhook: settings.from_webhook, http_status: failed ? 400 : 200, body } }];
